$ErrorActionPreference="Stop"
try{$R=Split-Path -Parent $MyInvocation.MyCommand.Path;Set-Location $R;if(!(Test-Path "docs\conditions")){throw "docs\conditions not found"};$bk="_backup_conditions28_"+(Get-Date -Format "yyyyMMdd-HHmmss");New-Item -ItemType Directory -Force $bk|Out-Null;foreach($s in Get-ChildItem "_payload\docs\conditions" -File){$d=Join-Path "docs\conditions" $s.Name;if(Test-Path $d){Copy-Item $d (Join-Path $bk $s.Name) -Force};Copy-Item $s.FullName $d -Force};Write-Host "CONDITIONS MODERNIZATION 28 COMPLETE" -ForegroundColor Green;Write-Host "10 condition pages rebuilt in place, not appended." -ForegroundColor Cyan;Write-Host ("Backup: "+$bk) -ForegroundColor Yellow}catch{Write-Host ("ERROR: "+$_.Exception.Message) -ForegroundColor Red};Read-Host "Press Enter to close"